import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    target = int(inputs[0] > 0)
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(torch.tensor(target))}
dataset = synth.Spec("r-drop-classification", generator=samples, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class PairedClassifier(nn.Module):
    def __init__(self):
        super().__init__()
        self.dropout = nn.Dropout(p=0.5)
        self.network = build("mlp", "tiny", in_features=4, out_features=2)
    def forward(self, inputs):
        paired_inputs = torch.cat((inputs, inputs), dim=0)
        return {"logits": self.network(self.dropout(paired_inputs))}
trainer = Trainer(PairedClassifier(), train, recipe="structured-objective", recipe_config={"loss": "r-drop", "loss_kwargs": {"alpha": 1.0}, "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"batch": "targets"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
